import sys
input = sys.stdin.read

def solve():
    data = input().split()
    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    # Initialize distances with a large number
    distances = [float('inf')] * n

    # Forward pass to find nearest 0 on the left
    last_zero_pos = -1
    for i in range(n):
        if a[i] == 0:
            last_zero_pos = i
        if last_zero_pos != -1:
            distances[i] = i - last_zero_pos

    # Backward pass to find nearest 0 on the right
    last_zero_pos = -1
    for i in range(n-1, -1, -1):
        if a[i] == 0:
            last_zero_pos = i
        if last_zero_pos != -1:
            distances[i] = min(distances[i], last_zero_pos - i)

    # Print the results
    for d in distances:
        print(d)

solve()

